using Microsoft.Extensions.Configuration;
namespace Demo.Security
{
    public class CryptoService
    {
        private readonly string _key;
        public CryptoService(IConfiguration config)
        {
            _key = config["Security:EncryptionKey"]
                ?? throw new InvalidOperationException("Security:EncryptionKey es requerida — configurarla antes de arrancar");
        }
        public string KeyFingerprint() => _key.Length.ToString();
    }
}
